(function() {
  CardSpoke_MODS.register({
    name: 'Sunrise',
    hooks: {
      onThemeChange: function(themeData) {
        var root = document.documentElement;
        if (themeData && themeData.isDark) {
          root.style.setProperty('--bg-gradient-start', '#2a1810');
          root.style.setProperty('--bg-gradient-end', '#1a1015');
        } else {
          root.style.setProperty('--bg-gradient-start', '#fff5eb');
          root.style.setProperty('--bg-gradient-end', '#fff0e0');
        }
      }
    }
  });
})()

