:root {
  --bg-primary: #fff5eb;
  --bg-secondary: #fff0e0;
  --bg-tertiary: #ffe8d0;
  --bg-card: #fffaf5;
  --bg-hover: #ffedda;
  --bg-active: #ffe2c8;
  --bg-input: #fff8f0;
  --bg-overlay: rgba(255, 240, 224, 0.9);
  --bg-gradient-start: #fff5eb;
  --bg-gradient-end: #fff0e0;
  --bg-sidebar: linear-gradient(180deg, var(--bg-gradient-start), var(--bg-gradient-end));
  --text-primary: #4a2c15;
  --text-secondary: #7a5535;
  --text-muted: #a8845a;
  --text-link: #c4692a;
  --text-heading: #3a1e0a;
  --text-inverse: #fff5eb;
  --accent-primary: #e87830;
  --accent-secondary: #d4622a;
  --accent-hover: #f08840;
  --accent-border: #f0c8a0;
  --accent-glow: rgba(232, 120, 48, 0.15);
  --accent-gradient: linear-gradient(135deg, #f0a060, #e87830);
}

.cs-app-shell {
  background: linear-gradient(135deg, var(--bg-primary), var(--bg-secondary), var(--bg-tertiary));
  transition: background 0.6s ease-in-out;
}

.cs-card {
  background: var(--bg-card);
  border: 1px solid var(--accent-border);
  border-radius: 8px;
  box-shadow: 0 2px 12px rgba(232, 120, 48, 0.08);
  transition: box-shadow 0.3s ease, border-color 0.3s ease;
}

.cs-card:hover {
  box-shadow: 0 4px 20px rgba(232, 120, 48, 0.15);
  border-color: var(--accent-primary);
}

.cs-sidebar {
  background: var(--bg-sidebar);
  border-right: 1px solid var(--accent-border);
}

.cs-header {
  background: linear-gradient(90deg, var(--accent-primary), var(--accent-secondary));
  color: var(--text-inverse);
}

.cs-btn-primary {
  background: var(--accent-gradient);
  color: var(--text-inverse);
  border: none;
  border-radius: 6px;
  padding: 8px 16px;
  transition: opacity 0.2s ease;
}

.cs-btn-primary:hover {
  opacity: 0.9;
}

.cs-input {
  background: var(--bg-input);
  border: 1px solid var(--accent-border);
  color: var(--text-primary);
  border-radius: 6px;
  padding: 8px 12px;
  transition: border-color 0.2s ease;
}

.cs-input:focus {
  border-color: var(--accent-primary);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

.cs-tag {
  background: var(--bg-hover);
  color: var(--accent-primary);
  border-radius: 12px;
  padding: 2px 10px;
  font-size: 0.85em;
}

.cs-scrollbar::-webkit-scrollbar-thumb {
  background: var(--accent-border);
  border-radius: 4px;
}

.cs-scrollbar::-webkit-scrollbar-thumb:hover {
  background: var(--accent-primary);
}
